<?php
final class Invoice {
 public static function show(int $id): never {
  $u=require_user();$r=row("SELECT i.number,i.created_at,p.amount,p.currency,p.provider_payment_id,p.user_id,u.name,u.email,u.company,CASE p.purpose WHEN 'ai_credits' THEN CONCAT(p.ai_credits, ' AI credits') WHEN 'service' THEN COALESCE(h.service, 'SEO service') ELSE pl.name END AS plan FROM invoices i JOIN payments p ON p.id=i.payment_id JOIN users u ON u.id=p.user_id JOIN plans pl ON pl.id=p.plan_id LEFT JOIN human_service_requests h ON h.id=p.service_request_id WHERE i.id=?",[$id]);if(!$r)fail('Invoice not found.',404);if(!is_admin()&&$r['user_id']!=$u['id'])fail('This invoice belongs to another account.',403);
  $title='Invoice '.$r['number'];require ROOT.'/includes/header.php';echo '<main class="container narrow" id="main"><div class="card"><span class="eyebrow">'.e(setting('site_name','SEO Zentro')).'</span><h1>'.e($title).'</h1><p>'.e($r['created_at']).'</p><h3>Billed to</h3><p>'.e($r['name']).'<br>'.e($r['company']).'<br>'.e($r['email']).'</p>';table(['plan'=>'Description','amount'=>'Amount (paise)','currency'=>'Currency'],[$r]);echo '<h2>Total paid: '.money((int)$r['amount']).'</h2><p>Payment reference: '.e($r['provider_payment_id']).'</p><p class="small">Payment receipt. Configure the operator’s registered business and tax invoicing process before commercial launch.</p><button class="button no-print" data-print>Print / Save as PDF</button></div></main>';require ROOT.'/includes/footer.php';exit;
 }
}
